def _template_to_device(batch, device):
    """Move every tensor of a tuple/list/dict batch to `device`."""
    if isinstance(batch, torch.Tensor):
        return batch.to(device)
    if isinstance(batch, dict):
        return {k: _template_to_device(v, device) for k, v in batch.items()}
    if isinstance(batch, (list, tuple)):
        return type(batch)(_template_to_device(v, device) for v in batch)
    return batch


def _template_unpack(batch):
    """(inputs, targets) from a tuple/list/dict batch."""
    if isinstance(batch, dict):
        vals = list(batch.values())
        return vals[0], (vals[1] if len(vals) > 1 else None)
    if isinstance(batch, (list, tuple)):
        return batch[0], (batch[1] if len(batch) > 1 else None)
    return batch, None


class _TemplateDictDataset(torch.utils.data.Dataset):
    """Synthetic dataset yielding dict batches with the keys the source loop uses."""

    def __init__(self, x, y, keys):
        self.x, self.y, self.keys = x, y, list(keys)

    def __len__(self):
        return self.x.shape[0]

    def __getitem__(self, i):
        return {self.keys[0]: self.x[i], self.keys[1]: self.y[i]}


# ---- definitions kept from the source ----
class SiameseNetwork(nn.Module):
    """
        Siamese network for image similarity estimation.
        The network is composed of two identical networks, one for each input.
        The output of each network is concatenated and passed to a linear layer. 
        The output of the linear layer passed through a sigmoid function.
        `"FaceNet" <https://arxiv.org/pdf/1503.03832.pdf>`_ is a variant of the Siamese network.
        This implementation varies from FaceNet as we use the `ResNet-18` model from
        `"Deep Residual Learning for Image Recognition" <https://arxiv.org/pdf/1512.03385.pdf>`_ as our feature extractor.
        In addition, we aren't using `TripletLoss` as the MNIST dataset is simple, so `BCELoss` can do the trick.
    """
    def __init__(self):
        super(SiameseNetwork, self).__init__()
        # get resnet model
        self.resnet = torchvision.models.resnet18(weights=None)

        # over-write the first conv layer to be able to read MNIST images
        # as resnet18 reads (3,x,x) where 3 is RGB channels
        # whereas MNIST has (1,x,x) where 1 is a gray-scale channel
        self.resnet.conv1 = nn.Conv2d(1, 64, kernel_size=(7, 7), stride=(2, 2), padding=(3, 3), bias=False)
        self.fc_in_features = self.resnet.fc.in_features
        
        # remove the last layer of resnet18 (linear layer which is before avgpool layer)
        self.resnet = torch.nn.Sequential(*(list(self.resnet.children())[:-1]))

        # add linear layers to compare between the features of the two images
        self.fc = nn.Sequential(
            nn.Linear(self.fc_in_features * 2, 256),
            nn.ReLU(inplace=True),
            nn.Linear(256, 1),
        )

        self.sigmoid = nn.Sigmoid()

        # initialize the weights
        self.resnet.apply(self.init_weights)
        self.fc.apply(self.init_weights)
        
    def init_weights(self, m):
        if isinstance(m, nn.Linear):
            torch.nn.init.xavier_uniform_(m.weight)
            m.bias.data.fill_(0.01)

    def forward_once(self, x):
        output = self.resnet(x)
        output = output.view(output.size()[0], -1)
        return output

    def forward(self, input1, input2):
        # get two images' features
        output1 = self.forward_once(input1)
        output2 = self.forward_once(input2)

        # concatenate both images' features
        output = torch.cat((output1, output2), 1)

        # pass the concatenation to the linear layers
        output = self.fc(output)

        # pass the out of the linear layers to sigmoid layer
        output = self.sigmoid(output)
        
        return output


class APP_MATCHER(Dataset):
    def __init__(self, root, train, download=False):
        super(APP_MATCHER, self).__init__()

        # get MNIST dataset
        self.dataset = datasets.MNIST(root, train=train, download=download)
        
        # as `self.dataset.data`'s shape is (Nx28x28), where N is the number of
        # examples in MNIST dataset, a single example has the dimensions of
        # (28x28) for (WxH), where W and H are the width and the height of the image. 
        # However, every example should have (CxWxH) dimensions where C is the number 
        # of channels to be passed to the network. As MNIST contains gray-scale images, 
        # we add an additional dimension to corresponds to the number of channels.
        self.data = self.dataset.data.unsqueeze(1).clone()

        self.group_examples()

    def group_examples(self):
        """
            To ease the accessibility of data based on the class, we will use `group_examples` to group 
            examples based on class. 
            
            Every key in `grouped_examples` corresponds to a class in MNIST dataset. For every key in 
            `grouped_examples`, every value will conform to all of the indices for the MNIST 
            dataset examples that correspond to that key.
        """

        # get the targets from MNIST dataset
        np_arr = np.array(self.dataset.targets.clone(), dtype=None, copy=None)
        
        # group examples based on class
        self.grouped_examples = {}
        for i in range(0,10):
            self.grouped_examples[i] = np.where((np_arr==i))[0]
    
    def __len__(self):
        return self.data.shape[0]
    
    def __getitem__(self, index):
        """
            For every example, we will select two images. There are two cases, 
            positive and negative examples. For positive examples, we will have two 
            images from the same class. For negative examples, we will have two images 
            from different classes.

            Given an index, if the index is even, we will pick the second image from the same class, 
            but it won't be the same image we chose for the first class. This is used to ensure the positive
            example isn't trivial as the network would easily distinguish the similarity between same images. However,
            if the network were given two different images from the same class, the network will need to learn 
            the similarity between two different images representing the same class. If the index is odd, we will 
            pick the second image from a different class than the first image.
        """

        # pick some random class for the first image
        selected_class = random.randint(0, 9)

        # pick a random index for the first image in the grouped indices based of the label
        # of the class
        random_index_1 = random.randint(0, self.grouped_examples[selected_class].shape[0]-1)
        
        # pick the index to get the first image
        index_1 = self.grouped_examples[selected_class][random_index_1]

        # get the first image
        image_1 = self.data[index_1].clone().float()

        # same class
        if index % 2 == 0:
            # pick a random index for the second image
            random_index_2 = random.randint(0, self.grouped_examples[selected_class].shape[0]-1)
            
            # ensure that the index of the second image isn't the same as the first image
            while random_index_2 == random_index_1:
                random_index_2 = random.randint(0, self.grouped_examples[selected_class].shape[0]-1)
            
            # pick the index to get the second image
            index_2 = self.grouped_examples[selected_class][random_index_2]

            # get the second image
            image_2 = self.data[index_2].clone().float()

            # set the label for this example to be positive (1)
            target = torch.tensor(1, dtype=torch.float)
        
        # different class
        else:
            # pick a random class
            other_selected_class = random.randint(0, 9)

            # ensure that the class of the second image isn't the same as the first image
            while other_selected_class == selected_class:
                other_selected_class = random.randint(0, 9)

            
            # pick a random index for the second image in the grouped indices based of the label
            # of the class
            random_index_2 = random.randint(0, self.grouped_examples[other_selected_class].shape[0]-1)

            # pick the index to get the second image
            index_2 = self.grouped_examples[other_selected_class][random_index_2]

            # get the second image
            image_2 = self.data[index_2].clone().float()

            # set the label for this example to be negative (0)
            target = torch.tensor(0, dtype=torch.float)

        return image_1, image_2, target


# ---- FL client interface ----
def build_model(config: dict) -> nn.Module:
    """Returns the training model; config['model_kwargs'] overrides constructor kwargs."""
    kwargs = dict(config.get("model_kwargs", {}))
    model = SiameseNetwork(**kwargs)
    return model

def build_dataloader(config: dict, split: str = "train") -> torch.utils.data.DataLoader:
    """R2: try the dataset constructions found in the source (data root bound to
    config["data_path"]); each is probed (len + first item) inside try/except. When
    none works, synthetic data is used only if config["allow_synthetic_data"]."""
    local = config.get("local", {})
    batch_size = int(local.get("batch_size", config.get("batch_size", 16)))
    num_workers = int(local.get("num_workers", 0))
    data_path = str(config.get("data_path", "."))
    seed = int(config.get("seed", 42))
    dataset, errors, collate = None, [], None
    # candidate 1: local APP_MATCHER (source line 283, feeds the training loader)
    if dataset is None:
        try:
            _ds = APP_MATCHER(data_path, train=True, download=True)
            _n = len(_ds)
            if _n <= 0:
                raise ValueError("empty dataset")
            _ = _ds[0]
            dataset = _ds
        except Exception as e:  # noqa: BLE001
            errors.append("candidate 1 (APP_MATCHER): %s: %s" % (type(e).__name__, str(e)[:120]))
    if dataset is None:
        if not config.get("allow_synthetic_data", False):
            raise FileNotFoundError(
                "no dataset could be built from data_path=%r (%s) and allow_synthetic_data is False"
                % (data_path, "; ".join(errors) or "no candidates"))
        dataset = _template_synthetic_dataset(config, seed)
    n_total = len(dataset)
    n_val = max(1, int(0.1 * n_total)) if n_total >= 2 else 0
    train_ds, val_ds = torch.utils.data.random_split(
        dataset, [n_total - n_val, n_val], generator=torch.Generator().manual_seed(seed))
    chosen = train_ds if split == "train" else val_ds
    return torch.utils.data.DataLoader(
        chosen, batch_size=batch_size, shuffle=(split == "train"), num_workers=num_workers,
        collate_fn=collate, drop_last=(split == "train" and len(chosen) > batch_size))


def _template_synthetic_dataset(config: dict, seed: int = 42):
    """R4 synthetic stand-in (only used when allow_synthetic_data=True).
    input (1, 28, 28) (float); target kind 'binary'.
    Evidence: catalogue:MNIST=(1, 28, 28),10; model:first-Conv2d.in_channels=1; model:last-Linear.out_features=1"""
    input_shape = tuple(config.get("synthetic_input_shape", (1, 28, 28)))
    n = int(config.get("synthetic_num_samples", 256))
    g = torch.Generator().manual_seed(seed)
    x = torch.randn((n, *input_shape), generator=g)
    y = torch.randint(0, 2, (n,), generator=g).float()
    return torch.utils.data.TensorDataset(x, y)

def train_step(model: nn.Module, batch, optimizer, config: dict) -> torch.Tensor:
    """R3: forward + loss extracted from the training loop at line 196 in train(). The FL runtime performs
    zero_grad/backward/step; this function must only return the loss tensor."""
    device = next(model.parameters()).device
    batch = _template_to_device(batch, device)
    (images_1, images_2, targets) = batch
    batch_idx = 0
    criterion = nn.BCELoss()
    images_1, images_2, targets = (images_1.to(device), images_2.to(device), targets.to(device))
    outputs = model(images_1, images_2).squeeze()
    loss = criterion(outputs, targets)
    return loss


def build_optimizer(model: nn.Module, config: dict):
    """Optimizer as declared in the source (informational: the FL runtime owns the optimizer)."""
    lr = config.get("learning_rate", None)
    try:
        opt = torch.optim.Adadelta(model.parameters(), lr=1.0)
    except Exception:
        opt = torch.optim.AdamW(model.parameters(), lr=lr or 1e-3)
    if lr is not None:
        for g in opt.param_groups:
            g["lr"] = lr
    return opt
